    def __init__(self, in_ch, out_ch):
        super().__init__()
        self.block = torch.nn.Sequential(torch.nn.Conv2d(in_ch, out_ch, kernel_size=3, padding=1, bias=False), torch.nn.BatchNorm2d(out_ch), torch.nn.ReLU(inplace=True), torch.nn.Conv2d(out_ch, out_ch, kernel_size=3, padding=1, bias=False), torch.nn.BatchNorm2d(out_ch), torch.nn.ReLU(inplace=True), torch.nn.MaxPool2d(2), torch.nn.Dropout(0.08))

    def forward(self, x):
