        self.features = torch.nn.Sequential(type(1, 32), type(32, 64), type(64, 128))
        self.pool = torch.nn.AdaptiveAvgPool2d(1)
        self.classifier = torch.nn.Sequential(torch.nn.Flatten(), torch.nn.Linear(128, 128), torch.nn.ReLU(inplace=True), torch.nn.Dropout(0.2), torch.nn.Linear(128, num_classes))

    def forward(self, x):
        x = self.features(x)
        x = self.pool(x)
